import { z } from 'zod';
import { AssetClass } from './basket-asset';
import { Address, AssetId, chainFamily, isAddressOf } from './chain';
import { Provenance } from './enums';
import { TrackedOracle } from './universe';

// The asset universe of one chain (docs/risk/PLAN-ASSETS.md, ASSET-1): every token of the classes the
// product knows, whether or not a plan may hold it, each with a status and the reason for it. One file
// per chain under scripts/risk/assets/, generated by `pnpm risk:assets <chain>` from reads and a reviewed
// table of verdicts, and committed (DA2). Additive: the stock list of universe.ts is not changed, and a
// stock row here names its row there instead of copying it.
//
// Nothing in a row is a price, a TVL, a supply or a yield. Those are observations with their own time
// (asset_observations, risk_price_observations), so a figure never sits in a committed file older than
// the hour it was read.

/** The chains the universe enumerates. Base is not (gate BASE). */
export const UniverseChain = z.enum(['solana', 'robinhood']);
export type UniverseChain = z.infer<typeof UniverseChain>;

/** A calendar day, YYYY-MM-DD. */
const Day = z
  .string()
  .regex(/^\d{4}-\d{2}-\d{2}$/, 'expected YYYY-MM-DD')
  .refine((d) => {
    const t = new Date(`${d}T00:00:00Z`);
    return !Number.isNaN(t.getTime()) && t.toISOString().startsWith(d);
  }, 'not a calendar day');
const Reason = z.string().min(1);

/** Where a row or a list came from. */
const Stamp = {
  source: z.string().min(1),
  fetchedAt: z.string().datetime(),
  method: z.string().min(1),
  provenance: Provenance,
};

/**
 * The fine category of a token (DA1). Each maps to one `AssetClass` or to none (`CATEGORY_CLASS`); a
 * row's `cls` is always its category's. Proposed by the orchestrator on 2026-10-10 for Rodrigo to confirm.
 */
export const UniverseCategory = z.enum([
  'tokenized_stock',
  'tokenized_etf',
  'tokenized_gold',
  'tokenized_commodity',
  /** A fund of treasuries or money-market paper anyone may hold (USDY, SGOV). */
  'treasury_fund_open',
  /** The same behind an allowlist (BUIDL, OUSG): a vault cannot be put on one (DA4). */
  'treasury_fund_permissioned',
  /** The deposit token of a lending market (kUSDC, jlUSDC, steakUSDG). */
  'lending_deposit',
  'private_credit',
  'basis_strategy',
  /** A protocol's savings rate on its own dollar (sUSDS). */
  'savings_rate',
  /** A token that matures on a date (a Pendle PT, a bond): the engine models no maturity. */
  'fixed_maturity',
  /** A dollar backed by cash and bills (USDC, USDT, USDG, PYUSD). */
  'stablecoin_usd',
  /** A dollar backed by positions, not by cash (USDe). */
  'stablecoin_synthetic',
  /** A stablecoin of another currency (EURC); the row carries `currency`. */
  'stablecoin_other',
  'native',
  'liquid_staking',
  'wrapped_btc',
  'wrapped_eth',
  /** Another chain's token held through a bridge or a custodian, not BTC or ETH. */
  'wrapped_other',
  'governance',
  /** A share in a pool: the vault cannot hold one. */
  'lp_share',
  /** A claim on a yield stream apart from its principal (a Pendle YT): the vault cannot hold one. */
  'yield_claim',
  /** None of the above; the row says why in `clsReason`. */
  'other',
]);
export type UniverseCategory = z.infer<typeof UniverseCategory>;

/** The class each category maps to, or null where the vault's classes have none. */
export const CATEGORY_CLASS: Record<UniverseCategory, AssetClass | null> = {
  tokenized_stock: 'stock',
  tokenized_etf: 'etf',
  tokenized_gold: 'gold',
  tokenized_commodity: 'commodity',
  treasury_fund_open: 'dollar_yield',
  treasury_fund_permissioned: 'dollar_yield',
  lending_deposit: 'dollar_yield',
  private_credit: 'dollar_yield',
  basis_strategy: 'dollar_yield',
  savings_rate: 'dollar_yield',
  fixed_maturity: 'dollar_yield',
  stablecoin_usd: 'cash',
  stablecoin_synthetic: 'cash',
  stablecoin_other: 'cash',
  native: 'crypto',
  liquid_staking: 'crypto',
  wrapped_btc: 'crypto',
  wrapped_eth: 'crypto',
  wrapped_other: 'crypto',
  governance: 'crypto',
  lp_share: null,
  yield_claim: null,
  other: null,
};

/**
 * The four kinds of dollar yield. The same values as `LegType` in packages/engine/src/personal/leg-types.ts,
 * which this package cannot import; tests/asset-universe-schema.test.ts holds the two equal.
 */
export const UniverseLegType = z.enum(['rate', 'credit', 'basis', 'market_deposit']);
export type UniverseLegType = z.infer<typeof UniverseLegType>;

/** Where a statement about a token was read: a URL, or a document of this repository. */
export const UniverseSource = z.strictObject({
  url: z.string().regex(/^(?:https?:\/\/\S+|(?:docs|content|scripts|fixtures|packages)\/\S+)$/),
  title: z.string().min(1),
  readOn: Day,
});
export type UniverseSource = z.infer<typeof UniverseSource>;

/** Who may act on a token, as read. `holder` null means the read says nobody, or `reason` says why it is unknown. */
export const UniverseAuthority = z
  .strictObject({
    holder: z.string().min(1).nullable(),
    reason: Reason.nullable(),
    /** The read that says so: the account field, the storage slot, the function called. */
    read: z.string().min(1),
  })
  .refine((a) => (a.holder === null) === (a.reason !== null), {
    message: 'a holder or the reason there is none',
    path: ['reason'],
  });
export type UniverseAuthority = z.infer<typeof UniverseAuthority>;

/** The reason a tracked stock's oracle and pools are null: they are read in its tracked row. */
export const IN_TRACKED_ROW = 'in_tracked_row';

/** What a row's chain allows: its standards, where its symbol may come from, its authorities by name. */
export const CHAIN_FIELDS = {
  solana: {
    standards: ['spl', 'token2022', 'other'],
    symbolFrom: ['metaplex', 'token_metadata_extension', 'listing'],
  },
  robinhood: {
    standards: ['erc20', 'erc4626', 'native', 'other'],
    symbolFrom: ['erc20', 'native', 'listing'],
  },
} as const;

/** The authorities each family's row carries, by name: exactly these. */
export const AUTHORITY_KEYS = {
  solana: ['mint', 'freeze', 'permanentDelegate'],
  evm: ['owner', 'admin'],
} as const;

/** One property of an EVM token's code, as read. `value` null carries the reason it is unknown. */
const EvmFlag = z
  .strictObject({
    value: z.boolean().nullable(),
    reason: Reason.nullable(),
    /** How it was read: the EIP-1967 slot, a function selector in the bytecode, the verified source. */
    read: z.string().min(1),
  })
  .refine((f) => (f.value === null) === (f.reason !== null), {
    message: 'a value or the reason it is unknown',
    path: ['reason'],
  });

export const UniverseExtensions = z.discriminatedUnion('family', [
  /** Token-2022 extensions by name, as the mint account holds them. A classic SPL mint has none. */
  z.strictObject({ family: z.literal('solana'), names: z.array(z.string().min(1)) }),
  z.strictObject({
    family: z.literal('evm'),
    proxy: EvmFlag,
    /** The implementation behind a proxy, lower case: set exactly when `proxy` is true. */
    implementation: z
      .string()
      .regex(/^0x[0-9a-f]{40}$/)
      .nullable(),
    pausable: EvmFlag,
    blacklist: EvmFlag,
  }),
]);
export type UniverseExtensions = z.infer<typeof UniverseExtensions>;

/** How the token is made and redeemed at its source, as published. */
export const UniverseMintRedeem = z.strictObject({
  primary: z.enum(['issuer', 'protocol', 'bridge', 'staking', 'none']),
  /** The path in words, as the source says it. */
  description: z.string().min(1),
  kyc: z.boolean().nullable(),
  /** The minimum, in the source's words; null where it publishes none. */
  minimum: z.string().min(1).nullable(),
  /** How long a redemption takes, in the source's words; null where it publishes none. */
  settlement: z.string().min(1).nullable(),
  source: z.string().min(1),
});
export type UniverseMintRedeem = z.infer<typeof UniverseMintRedeem>;

/** A dollar-yield token's kind of yield, each with where it was read. */
export const UniverseLeg = z.strictObject({
  type: UniverseLegType,
  source: z.string().min(1),
  readOn: Day,
});

/** The fields a reviewed verdict sets (`scripts/risk/assets/<chain>.verdicts.json`). Never read from a chain. */
const VerdictFields = {
  category: UniverseCategory,
  status: z.enum(['listed', 'candidate', 'held_out', 'excluded']),
  statusReason: Reason,
  /** The note and section where a research verdict exists, else null. */
  verdictSource: z.string().min(1).nullable(),
  issuer: z.string().min(1).nullable(),
  issuerReason: Reason.nullable(),
  issuerKind: z
    .enum([
      'regulated_fund_manager',
      'bank',
      'broker',
      'tokenization_issuer',
      'stablecoin_issuer',
      'defi_protocol',
      'bridge',
      'chain_native',
    ])
    .nullable(),
  /** In the form the shelf uses: `NVDA` for NVDAx, the token's own symbol for a yield token. */
  underlying: z.string().min(1).nullable(),
  underlyingReason: Reason.nullable(),
  /** ISO 4217 where the token is not counted in dollars. */
  currency: z
    .string()
    .regex(/^[A-Z]{3}$/)
    .refine((c) => c !== 'USD', 'dollars carry no currency')
    .nullable(),
  /** A dollar-yield token's kinds of yield; null with the reason where none was read, never guessed. Other classes: null and null. */
  legTypes: z.array(UniverseLeg).min(1).nullable(),
  legTypesReason: Reason.nullable(),
  yieldMechanism: z
    .enum(['accruing_price', 'rebasing', 'exchange_rate', 'distribution', 'none'])
    .nullable(),
  yieldMechanismReason: Reason.nullable(),
  access: z.enum(['open', 'permissioned', 'front_end_geo_blocked']).nullable(),
  accessReason: Reason.nullable(),
  mintRedeem: UniverseMintRedeem.nullable(),
  mintRedeemReason: Reason.nullable(),
  sources: z.array(UniverseSource).min(1),
  /** What the verdict says that was not read on a source. */
  unverified: z.array(z.string().min(1)),
};

export const UniverseAssetBase = z.strictObject({
  // identity, read on chain
  id: AssetId,
  chain: UniverseChain,
  address: Address,
  /** As the chain answers it; where the chain holds none, the listing's, said in `read.symbolFrom`. */
  symbol: z.string().min(1),
  name: z.string().min(1).nullable(),
  nameReason: Reason.nullable(),
  decimals: z.number().int().min(0).max(36),
  standard: z.enum(['spl', 'token2022', 'erc20', 'erc4626', 'native', 'other']),
  standardNote: z.string().min(1).nullable(),
  extensions: UniverseExtensions.nullable(),
  extensionsReason: Reason.nullable(),
  /** Solana: mint, freeze, permanentDelegate. EVM: owner, admin. Null for a chain's native token. */
  authorities: z.record(z.string().min(1), UniverseAuthority).nullable(),
  authoritiesReason: Reason.nullable(),
  /** The identity read: how, when, at which slot or block, and where the symbol came from. */
  read: z.strictObject({
    method: z.string().min(1),
    at: z.string().datetime(),
    /** The slot on Solana, the block on EVM. */
    height: z.number().int().min(0),
    symbolFrom: z.enum(['metaplex', 'token_metadata_extension', 'erc20', 'native', 'listing']),
  }),
  /** Every tag the listing carries (Jupiter's on Solana), as it carries them. */
  listingTags: z.array(z.string().min(1)),
  /** Robinhood Chain: the issuer's registry row, kept as it answered beside the chain's own answers. */
  issuerRegistry: z
    .strictObject({
      symbol: z.string().min(1),
      name: z.string().min(1).nullable(),
      decimals: z.number().int().min(0).max(36).nullable(),
      status: z.string().min(1).nullable(),
      isin: z.string().min(1).nullable(),
      /** In the registry's own text. */
      multiplier: z.string().min(1).nullable(),
    })
    .nullable(),

  // what it is, from the issuer and the research
  ...VerdictFields,
  /** The category's class (`CATEGORY_CLASS`), or null with the reason when the category has none. */
  cls: AssetClass.nullable(),
  clsReason: Reason.nullable(),
  /** Where there is a Scope entry or a Chainlink feed. A tracked stock's oracle is in its tracked row. */
  oracle: TrackedOracle.nullable(),
  oracleReason: Reason.nullable(),
  /** Feeds named by a source and never read (a Pyth feed, DU4). */
  unverifiedOracles: z.array(
    z.strictObject({ kind: z.literal('pyth'), ref: z.string().min(1), source: z.string().min(1) }),
  ),

  // where it stands
  /**
   * Which layers set the verdict fields, lowest first: `derived` (by the builder's stated method), `rule:<name>`
   * for each rule of the table it matched, in the table's order, and `verdict` for its own row.
   */
  decidedBy: z.array(z.string().regex(/^(?:derived|verdict|rule:.+)$/)).min(1),
  /** Where a `listed` row is on today's shelf. Empty for every other status. */
  listedIn: z.array(z.enum(['structurer_registry', 'deploy_record', 'tracked_stock'])),
  /** How many pools the chain's registry or cut knows for the token, and the file. `unconfirmed`: counted from a listing, not confirmed on chain. */
  pools: z
    .strictObject({
      confirmed: z.number().int().min(0),
      unconfirmed: z.number().int().min(0),
      file: z.string().min(1),
    })
    .nullable(),
  poolsReason: Reason.nullable(),
  /** A tracked stock's row in scripts/risk/universe/<chain>.json. Its pools and oracle are read there. */
  tracked: z.strictObject({ list: z.string().min(1), id: AssetId }).nullable(),
  /** A stock's sourced attributes in content/stocks/<chain>.json, by the symbol there. */
  attributes: z.strictObject({ file: z.string().min(1), symbol: z.string().min(1) }).nullable(),
  ...Stamp,
});

/** Each nullable field of a row with the field that holds its reason. */
const NULL_PAIRS = [
  ['name', 'nameReason'],
  ['extensions', 'extensionsReason'],
  ['authorities', 'authoritiesReason'],
  ['issuer', 'issuerReason'],
  ['underlying', 'underlyingReason'],
  ['yieldMechanism', 'yieldMechanismReason'],
  ['access', 'accessReason'],
  ['mintRedeem', 'mintRedeemReason'],
  ['oracle', 'oracleReason'],
  ['pools', 'poolsReason'],
  ['cls', 'clsReason'],
] as const;

type Base = z.infer<typeof UniverseAssetBase>;

export const UniverseAsset = UniverseAssetBase.superRefine((a: Base, ctx) => {
  const fail = (path: (string | number)[], message: string) =>
    ctx.addIssue({ code: 'custom', path, message });
  if (!a.id.startsWith(`${a.chain}:`)) fail(['id'], "the id starts with the asset's chain");
  const family = chainFamily(a.chain);
  if (!isAddressOf(family, a.address))
    fail(['address'], "the address is in the form of the asset's chain");
  for (const [field, reason] of NULL_PAIRS)
    if ((a[field] === null) !== (a[reason] !== null))
      fail([reason], `${field} or the reason it is null, never both and never neither`);
  if (a.cls !== CATEGORY_CLASS[a.category])
    fail(['cls'], `the class of ${a.category} is ${CATEGORY_CLASS[a.category] ?? 'none'}`);
  if (a.cls === 'dollar_yield') {
    if ((a.legTypes === null) === (a.legTypesReason === null))
      fail(['legTypesReason'], 'a dollar-yield row has its leg types or the reason there are none');
  } else if (a.legTypes !== null || a.legTypesReason !== null)
    fail(['legTypes'], 'only a dollar-yield row has leg types');
  if (a.category === 'stablecoin_other' && a.currency === null)
    fail(['currency'], 'a stablecoin of another currency names it');
  if (a.standard === 'other' && a.standardNote === null)
    fail(['standardNote'], 'another standard is named');
  if (a.extensions !== null && a.extensions.family !== family)
    fail(['extensions'], "the extensions are those of the asset's chain");
  if (a.authorities !== null) {
    for (const key of AUTHORITY_KEYS[family])
      if (!(key in a.authorities)) fail(['authorities', key], `the ${key} authority is read`);
    for (const key of Object.keys(a.authorities))
      if (!(AUTHORITY_KEYS[family] as readonly string[]).includes(key))
        fail(['authorities', key], `${key} is not an authority of a ${family} token`);
  }
  const allowed = CHAIN_FIELDS[a.chain];
  if (!(allowed.standards as readonly string[]).includes(a.standard))
    fail(['standard'], `${a.standard} is not a standard of ${a.chain}`);
  if (!(allowed.symbolFrom as readonly string[]).includes(a.read.symbolFrom))
    fail(['read', 'symbolFrom'], `${a.read.symbolFrom} is not a source of a ${a.chain} symbol`);
  if (a.chain !== 'robinhood' && a.issuerRegistry !== null)
    fail(['issuerRegistry'], "only Robinhood Chain's issuer registry is kept on a row");
  if (
    a.extensions?.family === 'evm' &&
    (a.extensions.implementation !== null) !== (a.extensions.proxy.value === true)
  )
    fail(
      ['extensions', 'implementation'],
      'an implementation is named exactly when the token is a proxy',
    );
  if (a.issuer !== null && a.issuerKind === null) fail(['issuerKind'], 'a named issuer has a kind');
  // statuses the plan states (DA4, DA7, prompt 5.3): what a vault cannot hold or a gate keeps out is never offered
  const offered = a.status === 'listed' || a.status === 'candidate';
  if (offered) {
    if (a.category === 'treasury_fund_permissioned' || a.access === 'permissioned')
      fail(
        ['status'],
        'a permissioned token is held out: a vault cannot be put on an allowlist (DA4)',
      );
    if (a.category === 'fixed_maturity')
      fail(['status'], 'a token with a maturity is held out: the engine models none');
    if (a.currency !== null)
      fail(['status'], 'a token in another currency is held out (USD-ONLY, DA7)');
    if (a.cls === null)
      fail(['status'], 'a token with no class is held out: the vault cannot hold it');
    if (a.cls === 'dollar_yield' && a.legTypes === null)
      fail(
        ['status'],
        'a dollar-yield token with no leg type is held out: its kind is never guessed',
      );
  }
  if ((a.status === 'listed') !== a.listedIn.length > 0)
    fail(['listedIn'], 'a listed row says where it is listed, and no other row does');
  if ((a.tracked !== null) !== a.listedIn.includes('tracked_stock'))
    fail(['tracked'], 'a tracked stock names its tracked row, and only a tracked stock does');
  if (a.tracked !== null) {
    if (a.tracked.id !== a.id) fail(['tracked', 'id'], 'a tracked row keeps its tracked id');
    if (a.oracle !== null || a.oracleReason !== IN_TRACKED_ROW)
      fail(['oracleReason'], "a tracked stock's oracle is read in its tracked row");
    if (a.pools !== null || a.poolsReason !== IN_TRACKED_ROW)
      fail(['poolsReason'], "a tracked stock's pools are read in its tracked row");
  } else if (a.oracleReason === IN_TRACKED_ROW || a.poolsReason === IN_TRACKED_ROW)
    fail(['tracked'], 'only a tracked stock points at a tracked row');
  if (a.oracle !== null) {
    const ok =
      a.oracle.kind === 'chainlink'
        ? family === 'evm' && isAddressOf('evm', a.oracle.ref)
        : a.chain === 'solana' &&
          /^(?:0|[1-9]\d{0,2})$/.test(a.oracle.ref) &&
          Number(a.oracle.ref) <= 511;
    if (!ok) fail(['oracle', 'ref'], "the oracle's kind and ref are those of the asset's chain");
  }
});
export type UniverseAsset = z.infer<typeof UniverseAsset>;

/** One read the list was made from, with what it cost. */
export const UniverseRead = z.strictObject({
  name: z.string().min(1),
  /** The call or URL, without any key. */
  what: z.string().min(1),
  at: z.string().datetime(),
  calls: z.number().int().min(0),
  durationMs: z.number().int().min(0),
  rows: z.number().int().min(0),
  errors: z.number().int().min(0),
});
export type UniverseRead = z.infer<typeof UniverseRead>;

export const UniverseCounts = z.strictObject({
  rows: z.number().int().min(0),
  byCategory: z.record(z.string(), z.number().int().min(1)),
  byStatus: z.record(z.string(), z.number().int().min(1)),
  /** By `cls`; a row with none is counted under `none`. */
  byClass: z.record(z.string(), z.number().int().min(1)),
  /** How many rows each layer of `decidedBy` set fields on. */
  byDecider: z.record(z.string(), z.number().int().min(1)),
  /** For each field that may be null, how many rows carry each reason. */
  nulls: z.record(z.string(), z.record(z.string(), z.number().int().min(1))),
});
export type UniverseCounts = z.infer<typeof UniverseCounts>;

const bump = (m: Record<string, number>, k: string) => {
  m[k] = (m[k] ?? 0) + 1;
};

/** The counts of a list's rows, as `UniverseList.counts` must state them. */
export function universeCounts(assets: readonly UniverseAsset[]): UniverseCounts {
  const byCategory: Record<string, number> = {};
  const byStatus: Record<string, number> = {};
  const byClass: Record<string, number> = {};
  const byDecider: Record<string, number> = {};
  const nulls: Record<string, Record<string, number>> = {};
  const nul = (field: string, reason: string) => {
    nulls[field] ??= {};
    bump(nulls[field], reason);
  };
  for (const a of assets) {
    bump(byCategory, a.category);
    bump(byStatus, a.status);
    bump(byClass, a.cls ?? 'none');
    for (const d of new Set(a.decidedBy)) bump(byDecider, d);
    for (const [field, reason] of NULL_PAIRS) {
      const why = a[reason];
      if (a[field] === null && why !== null) nul(field, why);
    }
    if (a.legTypes === null && a.legTypesReason !== null) nul('legTypes', a.legTypesReason);
    for (const [key, auth] of Object.entries(a.authorities ?? {}))
      if (auth.holder === null && auth.reason !== null) nul(`authorities.${key}`, auth.reason);
    if (a.extensions?.family === 'evm')
      for (const flag of ['proxy', 'pausable', 'blacklist'] as const) {
        const f = a.extensions[flag];
        if (f.value === null && f.reason !== null) nul(`extensions.${flag}`, f.reason);
      }
  }
  const sorted = <T>(m: Record<string, T>) =>
    Object.fromEntries(Object.entries(m).sort(([x], [y]) => (x < y ? -1 : x > y ? 1 : 0)));
  return {
    rows: assets.length,
    byCategory: sorted(byCategory),
    byStatus: sorted(byStatus),
    byClass: sorted(byClass),
    byDecider: sorted(byDecider),
    nulls: sorted(Object.fromEntries(Object.entries(nulls).map(([k, v]) => [k, sorted(v)]))),
  };
}

/** JSON with every object's keys in one order, so two equal counts compare equal however they were written. */
const canonical = (v: unknown): string =>
  JSON.stringify(v, (_k, x) =>
    x && typeof x === 'object' && !Array.isArray(x)
      ? Object.fromEntries(Object.entries(x).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)))
      : x,
  );

/** One chain's file. */
export const UniverseList = z
  .strictObject({
    chain: UniverseChain,
    ...Stamp,
    /** The files and listings the list was written from, by name. */
    inputs: z.record(z.string().min(1), z.string().min(1)),
    /** Every read, with its calls and duration. */
    reads: z.array(UniverseRead).min(1),
    counts: UniverseCounts,
    /** What the list does and does not decide, in words. */
    stated: z.record(z.string().min(1), z.string().min(1)),
    assets: z.array(UniverseAsset),
  })
  .superRefine((l, ctx) => {
    const fail = (path: (string | number)[], message: string) =>
      ctx.addIssue({ code: 'custom', path, message });
    if (!l.assets.every((a) => a.chain === l.chain))
      fail(['assets'], "every row is on the file's chain");
    const norm = (s: string) => (l.chain === 'solana' ? s : s.toLowerCase());
    if (new Set(l.assets.map((a) => norm(a.address))).size !== l.assets.length)
      fail(['assets'], 'one row per token address');
    if (new Set(l.assets.map((a) => a.id)).size !== l.assets.length)
      fail(['assets'], 'one row per id');
    if (canonical(l.counts) !== canonical(universeCounts(l.assets)))
      fail(['counts'], 'the counts are those of the rows');
  });
export type UniverseList = z.infer<typeof UniverseList>;

/** A reviewed verdict for one token address. The command refuses one for an address it did not read. */
export const UniverseVerdict = z.strictObject({
  address: Address,
  /** For the reader of the table; the command checks it against the chain's answer. */
  symbol: z.string().min(1),
  ...VerdictFields,
});
export type UniverseVerdict = z.infer<typeof UniverseVerdict>;

/**
 * A verdict for every token one listing names in one way (every token of the issuer's registry, every
 * token Jupiter tags `xstocks`). `match` is read by the chain's command, which says how in its README.
 * Fields left out are filled by the command from the reads, by a method it states.
 */
export const UniverseVerdictRule = z.strictObject({
  name: z.string().min(1),
  match: z.record(z.string().min(1), z.string().min(1)),
  /** What the rule sets. Its sources are the rule's own `sources`, not a field. */
  fields: z.strictObject(VerdictFields).omit({ sources: true }).partial(),
  sources: z.array(UniverseSource).min(1),
});
export type UniverseVerdictRule = z.infer<typeof UniverseVerdictRule>;

export const UniverseVerdicts = z
  .strictObject({
    chain: UniverseChain,
    reviewedOn: Day,
    note: z.string().min(1),
    rules: z.array(UniverseVerdictRule),
    verdicts: z.array(UniverseVerdict),
  })
  .refine(
    (v) =>
      new Set(v.verdicts.map((r) => (v.chain === 'solana' ? r.address : r.address.toLowerCase())))
        .size === v.verdicts.length,
    { message: 'one verdict per address', path: ['verdicts'] },
  )
  .refine((v) => new Set(v.rules.map((r) => r.name)).size === v.rules.length, {
    message: 'one rule per name',
    path: ['rules'],
  });
export type UniverseVerdicts = z.infer<typeof UniverseVerdicts>;
